/**
 * agent-sprite-data — base64 data-URIs of the 5 robot-ninja agent sprites.
 *
 * These are the SAME PNGs the web Galactic HQ uses (ui/public/agent-sprites/*.png,
 * 128x192 each). The mobile Agency World runs inside a react-native-webview loaded
 * from an inline HTML string (baseUrl ''), so it cannot fetch /agent-sprites/*.png
 * over the network. We embed them as data-URIs and expose them to the engine via
 * window.__AGENT_SPRITES__ so drawCharacter() can render the real sprite instead of
 * the procedural pixel-art fallback. Source of truth: mobile/assets/agent-sprites/.
 */
export const AGENT_SPRITE_DATA = {"claude":"data:image/png;base64,","opencode":"data:image/png;base64,","codex":"data:image/png;base64,","gemini":"data:image/png;base64,","default":"data:image/png;base64,"};

// Script tag injected into the engine HTML BEFORE the engine <script> runs.
export const AGENT_SPRITE_SCRIPT =
  '<script>window.__AGENT_SPRITES__=' + JSON.stringify(JSON.stringify(AGENT_SPRITE_DATA)) + ';</script>';
